import React, { useState, useEffect } from 'react';
import { Card, Button, Row, Col, Alert } from 'react-bootstrap';
import useAuth from '../hooks/useAuth';
import { getToken } from '../utils/localStorage';
import apiClient from '../api/apiClient';
import { createEntry, getAllEntries, getSummary } from '../api/entryApi';

const DebugInfo = () => {
  const { user } = useAuth();
  const [backendStatus, setBackendStatus] = useState('Checking...');
  const [authStatus, setAuthStatus] = useState('Checking...');
  const [testEntryResult, setTestEntryResult] = useState(null);
  const [testGetAllResult, setTestGetAllResult] = useState(null);
  const [testSummaryResult, setTestSummaryResult] = useState(null);
  const [backendVersion, setBackendVersion] = useState('Unknown');

  // Check backend connection
  useEffect(() => {
    const checkBackend = async () => {
      try {
        const response = await apiClient.get('/');
        setBackendStatus(`Connected: ${response.data.message || JSON.stringify(response.data)}`);
        setBackendVersion(response.headers['server'] || 'FastAPI');
      } catch (error) {
        setBackendStatus(`Error: ${error.message}`);
      }
    };
    
    checkBackend();
  }, []);

  // Check auth status
  useEffect(() => {
    const token = getToken();
    if (token && user) {
      setAuthStatus(`Authenticated as: ${user.username}, Token: ${token.substring(0, 15)}...`);
    } else {
      setAuthStatus('Not authenticated or missing token/user');
    }
  }, [user]);

  // Test creating an entry
  const testCreateEntry = async () => {
    if (!user) {
      setTestEntryResult('No user available to test');
      return;
    }

    try {
      setTestEntryResult('Testing...');
      
      // Prepare test data
      const testEntry = {
        name: 'Debug Test Entry',
        type: 'Income',
        amount: 100,
        date: new Date().toISOString()
      };
      
      console.log('Test entry payload:', testEntry);
      console.log('Username:', user.username);
      
      const response = await createEntry(user.username, testEntry);
      
      setTestEntryResult(`Success! Created entry with ID: ${response.id}`);
    } catch (error) {
      console.error('Test entry error:', error);
      setTestEntryResult(`Error: ${error.response?.data?.detail || error.message}`);
    }
  };

  // Test getting all entries
  const testGetAllEntries = async () => {
    if (!user) {
      setTestGetAllResult('No user available to test');
      return;
    }

    try {
      setTestGetAllResult('Testing...');
      
      const response = await getAllEntries(user.username);
      
      setTestGetAllResult(`Success! Got ${response.length} entries`);
    } catch (error) {
      console.error('Test get all error:', error);
      setTestGetAllResult(`Error: ${error.response?.data?.detail || error.message}`);
    }
  };

  // Test getting summary
  const testGetSummary = async () => {
    if (!user) {
      setTestSummaryResult('No user available to test');
      return;
    }

    try {
      setTestSummaryResult('Testing...');
      
      const response = await getSummary(user.username);
      
      setTestSummaryResult(`Success! Summary: Income=${response.total_income}, Expense=${response.total_expense}, Balance=${response.balance}`);
    } catch (error) {
      console.error('Test summary error:', error);
      setTestSummaryResult(`Error: ${error.response?.data?.detail || error.message}`);
    }
  };

  // Get API URL from environment
  const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:8000';

  return (
    <Card className="mb-4 bg-light">
      <Card.Header className="bg-info text-white">Debug Information</Card.Header>
      <Card.Body>
        <Row>
          <Col md={6}>
            <h5>Environment</h5>
            <ul>
              <li><strong>API URL:</strong> {apiUrl}</li>
              <li><strong>Backend Status:</strong> {backendStatus}</li>
              <li><strong>Backend Version:</strong> {backendVersion}</li>
              <li><strong>Auth Status:</strong> {authStatus}</li>
            </ul>
          </Col>
          
          <Col md={6}>
            <h5>User Object</h5>
            <pre className="bg-dark text-light p-2 rounded" style={{ maxHeight: '150px', overflow: 'auto' }}>
              {JSON.stringify(user, null, 2) || 'No user data'}
            </pre>
          </Col>
        </Row>
        
        <hr />
        
        <h5>API Tests</h5>
        <Row className="g-3">
          <Col md={4}>
            <Button 
              variant="warning" 
              onClick={testCreateEntry} 
              className="w-100 mb-2"
            >
              Test Create Entry
            </Button>
            {testEntryResult && (
              <Alert variant={testEntryResult.includes('Success') ? 'success' : 'danger'} className="mt-2 small p-2">
                {testEntryResult}
              </Alert>
            )}
          </Col>
          
          <Col md={4}>
            <Button 
              variant="warning" 
              onClick={testGetAllEntries} 
              className="w-100 mb-2"
            >
              Test Get All Entries
            </Button>
            {testGetAllResult && (
              <Alert variant={testGetAllResult.includes('Success') ? 'success' : 'danger'} className="mt-2 small p-2">
                {testGetAllResult}
              </Alert>
            )}
          </Col>
          
          <Col md={4}>
            <Button 
              variant="warning" 
              onClick={testGetSummary} 
              className="w-100 mb-2"
            >
              Test Get Summary
            </Button>
            {testSummaryResult && (
              <Alert variant={testSummaryResult.includes('Success') ? 'success' : 'danger'} className="mt-2 small p-2">
                {testSummaryResult}
              </Alert>
            )}
          </Col>
        </Row>
      </Card.Body>
    </Card>
  );
};

export default DebugInfo;
